#!/usr/bin/env node
/**
 * Re-import all transformed Convex data using `npx convex import --replace`.
 * Generated by transform-supabase-to-convex.ts — do not edit manually.
 */
import { execSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const TMP_DIR = path.resolve(__dirname, '..', 'artifacts', 'supabase-convex-transformed');

// Tables to import (in dependency order: parents first, then children)
const TABLES = [
  'authors',
  'books',
  'book_authors',
  'users',
  'follows',
  'profiles',
  'reviews',
  'reading_lists',
  'reading_list_items',
  'reading_progress',
  'groups',
  'group_members',
  'events',
  'notifications',
  'genres',
  'publishers',
];

function importTable(table) {
  const file = path.join(TMP_DIR, table, 'documents.jsonl');
  if (!fs.existsSync(file)) {
    console.log(`⏭ ${table}: skipped (no file)`);
    return;
  }
  const count = fs.readFileSync(file, 'utf8').trim().split('\n').length;
  console.log(`→ ${table}: ${count} rows ...`);
  try {
    execSync(
      `npx convex import --table ${table} --replace --yes "${file}"`,
      { stdio: 'inherit', cwd: path.resolve(__dirname, '..') }
    );
    console.log(`  ✓ ${table} imported`);
  } catch (err) {
    console.error(`  ✗ ${table} FAILED:`, err.message);
    process.exitCode = 1;
  }
}

async function main() {
  const summaryFile = path.join(TMP_DIR, 'summary.json');
  if (!fs.existsSync(summaryFile)) {
    console.error('ERROR: Run transform-supabase-to-convex.ts first');
    process.exit(1);
  }
  const summary = JSON.parse(fs.readFileSync(summaryFile, 'utf8'));
  console.log(`\n📦 Re-importing ${summary.tablesProcessed} tables (` +
    `${summary.totalRowsTransformed} rows total) into Convex\n`);

  for (const t of TABLES) {
    importTable(t);
  }

  console.log('\n✅ Import complete!');
}

main();
